addons.script:
// ---- type checks that do not depend on instanceof ----
function sqIsComp(it) { try { if (it instanceof CompItem) return true; } catch (e) {} try { return !!it && typeof it.numLayers === "number" && typeof it.layers === "object"; } catch (e2) { return false; } }
function sqIsFolder(it) { try { if (it instanceof FolderItem) return true; } catch (e) {} try { return !!it && typeof it.numItems === "number" && typeof it.items === "object" && typeof it.numLayers !== "number"; } catch (e2) { return false; } }
function sqIsCamOrLight(L) { try { if (L.property("ADBE Camera Options Group") || L.property("ADBE Light Options Group")) return true; } catch (e) {} return false; }
// Squeezy Duplicator: deep-duplicate comps so every nested precomp becomes its own copy
var roots = [];
var psel = app.project.selection;
for (var i = 0; i < psel.length; i++) if (sqIsComp(psel[i])) roots.push(psel[i]);
if (!roots.length && comp) roots.push(comp);
if (!roots.length) return "Select a comp in the Project panel (or open one).";

var suffix = String(params.suffix || ""), find = String(params.find || ""), repl = String(params.replace || "");
if (!suffix && !find) suffix = "_copy";
var keepWords = [];
var kw = String(params.keep || "").split(",");
for (var k = 0; k < kw.length; k++) { var w = kw[k].replace(/^\s+|\s+$/g, ""); if (w) keepWords.push(w.toLowerCase()); }

function newName(n) {
    var s = String(n);
    if (find) s = s.split(find).join(repl);
    if (suffix) s = s + suffix;
    if (s === String(n)) s = s + "_copy";
    return s;
}
function isShared(c) {
    var n = String(c.name).toLowerCase();
    for (var i = 0; i < keepWords.length; i++) if (n.indexOf(keepWords[i]) >= 0) return true;
    return false;
}

// folders: one new folder per run, mirroring sub-folders of the originals
var baseFolder = roots[0].parentFolder, outFolder = null, sub = {};
if (params.folder) {
    outFolder = app.project.items.addFolder(newName(roots[0].name) + " (Squeezy)");
    outFolder.parentFolder = baseFolder;
}
function folderFor(c) {
    if (!outFolder) return c.parentFolder;
    var pf = c.parentFolder;
    if (!pf || pf === baseFolder || pf === app.project.rootFolder) return outFolder;
    if (!sub[pf.id]) { sub[pf.id] = app.project.items.addFolder(pf.name); sub[pf.id].parentFolder = outFolder; }
    return sub[pf.id];
}

var map = {}, made = [], renames = [], shared = 0;
function dup(c, isRoot) {
    if (map[c.id]) return map[c.id];
    if (!isRoot && isShared(c)) { map[c.id] = c; shared++; return c; }   // the comp you picked is always copied
    var d = c.duplicate();
    d.name = newName(c.name);
    d.parentFolder = folderFor(c);
    map[c.id] = d;
    made.push(d);
    renames.push([c.name, d.name]);
    for (var i = 1; i <= d.numLayers; i++) {
        var L = d.layer(i);
        if (L.source && sqIsComp(L.source)) {
            var nd = dup(L.source);
            if (nd !== L.source) L.replaceSource(nd, false);
        }
    }
    return d;
}
var tops = [];
for (var r = 0; r < roots.length; r++) {
    tops.push(dup(roots[r], true));
}

// point expressions at the new comps (comp("Old") -> comp("New"))
var fixed = 0;
function fixExpr(group) {
    for (var i = 1; i <= group.numProperties; i++) {
        var p = group.property(i);
        if (p.propertyType === PropertyType.PROPERTY) {
            if (p.canSetExpression && p.expression) {
                var e = p.expression, e2 = e;
                for (var j = 0; j < renames.length; j++) {
                    e2 = e2.split('comp("' + renames[j][0] + '")').join('comp("' + renames[j][1] + '")');
                    e2 = e2.split("comp('" + renames[j][0] + "')").join("comp('" + renames[j][1] + "')");
                }
                if (e2 !== e) { try { p.expression = e2; fixed++; } catch (er) {} }
            }
        } else if (p.numProperties) fixExpr(p);
    }
}
if (params.expressions) {
    for (var m = 0; m < made.length; m++) for (var l = 1; l <= made[m].numLayers; l++) fixExpr(made[m].layer(l));
}
if (params.open && tops.length) { try { tops[0].openInViewer(); } catch (eo) {} }

return "Squeezy Duplicator: " + made.length + " comp" + (made.length === 1 ? "" : "s") + " copied"
    + (shared ? ", " + shared + " kept shared" : "") + (fixed ? ", " + fixed + " expression" + (fixed === 1 ? "" : "s") + " re-linked" : "");

// ---- type checks that do not depend on instanceof ----
function sqIsComp(it) { try { if (it instanceof CompItem) return true; } catch (e) {} try { return !!it && typeof it.numLayers === "number" && typeof it.layers === "object"; } catch (e2) { return false; } }
function sqIsFolder(it) { try { if (it instanceof FolderItem) return true; } catch (e) {} try { return !!it && typeof it.numItems === "number" && typeof it.items === "object" && typeof it.numLayers !== "number"; } catch (e2) { return false; } }
function sqIsCamOrLight(L) { try { if (L.property("ADBE Camera Options Group") || L.property("ADBE Light Options Group")) return true; } catch (e) {} return false; }
// ---- Squeezy add-on helpers (ExtendScript, ES3) ----
function sqFx(l) { return l.property("ADBE Effect Parade"); }
function sqCtrl(l, match, name, v) {
    var p = sqFx(l).property(name);
    if (p && p.matchName !== match) { p.remove(); p = null; }
    if (!p) { p = sqFx(l).addProperty(match); p.name = name; p = sqFx(l).property(name); }
    try { if (v !== undefined && v !== null) p.property(1).setValue(v); } catch (e) {}
    return sqFx(l).property(name);
}
function sqSlider(l, name, v) { return sqCtrl(l, "ADBE Slider Control", name, v); }
function sqCheckbox(l, name, v) { return sqCtrl(l, "ADBE Checkbox Control", name, v ? 1 : 0); }
function sqHex(h) { var n = parseInt(String(h).replace("#", ""), 16); return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255, 1]; }
function sqRemoveFx(l, prefix) {
    var fx = sqFx(l); if (!fx) return;
    for (var i = fx.numProperties; i >= 1; i--) if (String(fx.property(i).name).indexOf(prefix) === 0) fx.property(i).remove();
}
function sqRemoveKids(comp, l, prefix) {
    for (var i = comp.numLayers; i >= 1; i--) {
        var c = comp.layer(i);
        if (c.parent && c.parent.index === l.index && String(c.name).indexOf(prefix) === 0) c.remove();
    }
}
function sqEaseKeys(prop) {
    for (var k = 1; k <= prop.numKeys; k++) {
        var dims = 1; try { var v = prop.keyValue(k); if (v instanceof Array) dims = v.length; } catch (e) {}
        if (prop.propertyValueType === PropertyValueType.TwoD_SPATIAL || prop.propertyValueType === PropertyValueType.ThreeD_SPATIAL) dims = 1;
        var a = [], b = [];
        for (var d = 0; d < dims; d++) { a.push(new KeyframeEase(0, 45)); b.push(new KeyframeEase(0, 45)); }
        try { prop.setTemporalEaseAtKey(k, a, b); } catch (e2) {}
    }
}

// ---- pixel grid reveal (used by Pixel Scan Reveal and Block Flow) ----
// Builds a block matte + optional glowing block layer, both parented to the target layer.
function sqScan(comp, l, o) {
    var r = l.sourceRectAtTime(o.t0, false);
    if (!r || r.width < 1 || r.height < 1) throw new Error(l.name + " has nothing visible at the current time");
    var size = Math.max(4, o.size), cols, rows;
    do { cols = Math.ceil(r.width / size); rows = Math.ceil(r.height / size); if (cols * rows > 700) size *= 1.15; } while (cols * rows > 700);

    sqRemoveKids(comp, l, "SQ Scan ");
    sqRemoveFx(l, "SQ Scan ");
    sqSlider(l, "SQ Scan Progress", 0);
    sqSlider(l, "SQ Scan Random", o.random);
    sqSlider(l, "SQ Scan Glow Band", o.band);
    var pr = sqFx(l).property("SQ Scan Progress").property(1);
    pr.setValueAtTime(o.t0, 0);
    pr.setValueAtTime(o.t0 + o.dur, 100);
    sqEaseKeys(pr);

    var cells = [];
    for (var y = 0; y < rows; y++) for (var x = 0; x < cols; x++) {
        var cx = r.left + (x + 0.5) * size, cy = r.top + (y + 0.5) * size, u;
        var nx = cols > 1 ? x / (cols - 1) : 0, ny = rows > 1 ? y / (rows - 1) : 0;
        switch (o.dir) {
            case "rtl": u = 1 - nx; break;
            case "ttb": u = ny; break;
            case "btt": u = 1 - ny; break;
            case "center": u = Math.min(1, Math.sqrt((nx - 0.5) * (nx - 0.5) + (ny - 0.5) * (ny - 0.5)) / 0.7072); break;
            case "random": u = Math.random(); break;
            default: u = nx;
        }
        cells.push({ x: cx, y: cy, u: u, q: Math.random() });
    }

    function grid(name, glow) {
        var s = comp.layers.addShape();
        s.name = name;
        s.moveBefore(l);
        s.parent = l;
        try { s.property("ADBE Transform Group").property("ADBE Anchor Point").setValue([0, 0]); } catch (e) {}
        try { s.property("ADBE Transform Group").property("ADBE Position").setValue([0, 0]); } catch (e1) { try { s.property("ADBE Transform Group").property("ADBE Position").setValue([0, 0, 0]); } catch (e2) {} }
        var root = function () { return s.property("ADBE Root Vectors Group"); };
        var bs = glow ? size * 0.78 : size + 1;
        var col = glow ? sqHex(o.color) : [1, 1, 1, 1];
        for (var i = 0; i < cells.length; i++) {
            var c = cells[i], k = (c.u * 1).toFixed(4), qq = c.q.toFixed(4);
            var gi = root().addProperty("ADBE Vector Group").propertyIndex;
            var G = function () { return root().property(gi); };
            G().property("ADBE Vectors Group").addProperty("ADBE Vector Shape - Rect");
            G().property("ADBE Vectors Group").property(1).property("ADBE Vector Rect Size").setValue([bs, bs]);
            G().property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Fill");
            G().property("ADBE Vectors Group").property(2).property("ADBE Vector Fill Color").setValue(col);
            var T = G().property("ADBE Vector Transform Group");
            T.property("ADBE Vector Position").setValue([c.x, c.y]);
            var head = "var P=parent.effect(\"SQ Scan Progress\")(1)/100, R=parent.effect(\"SQ Scan Random\")(1)/100; var k=" + k + "*(1-R)+" + qq + "*R*0.999;";
            G().property("ADBE Vector Transform Group").property("ADBE Vector Group Opacity").expression = glow
                ? head + " var B=Math.max(parent.effect(\"SQ Scan Glow Band\")(1)/100,0.001), d=P-k*(1-B)-B*0.5; (P>0 && P<1 && d>=-B*0.5 && d<B*0.5) ? 100*(1-Math.abs(d)/(B*0.5)) : 0;"
                : head + " (P>=1 || (P>0 && P>=k)) ? 100 : 0;";
        }
        return s;
    }

    var m = grid("SQ Scan Matte · " + l.name, false);
    if (o.glow) {
        var g = grid("SQ Scan Glow · " + l.name, true);
        g.blendingMode = BlendingMode.ADD;
        var gl = sqFx(g).addProperty("ADBE Glo2");
        try { gl.property(3).setValue(Math.max(10, size * 0.8)); gl.property(4).setValue(1.6); } catch (eg) {}
    }
    var done = false;
    try { if (l.setTrackMatte) { l.setTrackMatte(m, TrackMatteType.ALPHA); done = true; } } catch (et) {}
    if (!done) { m.moveBefore(l); l.trackMatteType = TrackMatteType.ALPHA; }
    m.enabled = false;
    return cells.length;
}

// Squeezy add-on: Kashida Stretch v4
// Arabic text: the kashida (tatweel, U+0640) stretches the word: خولي -> خــــولي
// One clean set of controls on the layer (all keyframable):
//   Stretch amount    how long the kashida gets (number of kashida)
//   Pivot             where in the word it stretches (0% = first joint, 100% = last joint)
//   Stretch direction which way the word grows (Left / Right), the other side stays put
//   Bilateral push    grow both ways from the centre
// runs as function(params, comp, layers)
if (!comp) return "Open a composition first.";
if (params.action === "Remove") {
    var rm = 0;
    for (var r = 0; r < layers.length; r++) {
        var L0 = layers[r];
        if (!L0.property("ADBE Text Properties")) continue;
        var td0 = L0.property("ADBE Text Properties").property("ADBE Text Document");
        if (String(td0.expression).indexOf("SQ-KASHIDA") < 0 && !sqFx(L0).property("Stretch amount")) continue;
        td0.expression = "";
        var ap0 = L0.property("ADBE Transform Group").property("ADBE Anchor Point");
        if (String(ap0.expression).indexOf("SQ-KASHIDA") >= 0) ap0.expression = "";
        var fx0 = sqFx(L0);
        var names = ["Stretch amount", "Pivot", "Stretch direction", "Bilateral push"];
        for (var nn = 0; nn < names.length; nn++) { try { if (fx0.property(names[nn])) fx0.property(names[nn]).remove(); } catch (e0) {} }
        sqRemoveFx(L0, "SQ Kashida");     // older versions
        rm++;
    }
    return rm ? "Kashida removed from " + rm + " layer" + (rm > 1 ? "s" : "") : "Select a layer that has Kashida Stretch.";
}

var MODES = { "Each word": 0, "Longest word only": 2, "Every joint": 3 };
var mode = MODES[params.words]; if (mode === undefined) mode = 0;
var n = 0, skipped = 0;

// ---- sourceText: insert the kashida at the pivot joint(s) ----
var expr = [
 "// SQ-KASHIDA",
 "var N = Math.max(0, Math.round(effect(\"Stretch amount\")(1))), PV = Math.min(Math.max(effect(\"Pivot\")(1), 0), 100) / 100;",
 "var s = '' + value, MODE = " + mode + ";",
 "function ar(c){ var x = c.charCodeAt(0); return (x >= 0x0620 && x <= 0x064A) || (x >= 0x066E && x <= 0x06D3); }",
 "function joins(c){ return ar(c) && 'اأإآٱدذرزوؤةءژ'.indexOf(c) < 0; }",
 "var words = [], st = -1;",
 "for (var i = 0; i <= s.length; i++) { var ch = i < s.length ? s.charAt(i) : ' '; if (ar(ch) || ch == '\\u0640') { if (st < 0) st = i; } else if (st >= 0) { words.push([st, i]); st = -1; } }",
 "function cand(w){ var r = []; for (var j = w[0]; j < w[1] - 1; j++) { if (joins(s.charAt(j)) && ar(s.charAt(j + 1))) r.push(j + 1); } return r; }",
 "if (MODE == 2) { var best = null; for (var w = 0; w < words.length; w++) if (!best || words[w][1] - words[w][0] > best[1] - best[0]) best = words[w]; if (best) words = [best]; }",
 "var spots = [];",
 "for (var w2 = 0; w2 < words.length; w2++) { var c = cand(words[w2]); if (!c.length) continue;",
 "  if (MODE == 3) spots = spots.concat(c); else spots.push(c[Math.round(PV * (c.length - 1))]); }",
 "var run = ''; for (var q = 0; q < N; q++) run += '\\u0640';",
 "spots.sort(function (a, b) { return a - b; });",
 "var out = '', last = 0; for (var z = 0; z < spots.length; z++) { out += s.substring(last, spots[z]) + run; last = spots[z]; }",
 "out += s.substring(last); out;"
].join("\n");

// ---- anchor point: keep one side (or the centre) still while the word grows ----
// rest size = the text at a moment when Stretch amount is 0 (its first such keyframe), else now
var anchorExpr = [
 "// SQ-KASHIDA",
 "var A = effect(\"Stretch amount\")(1), tr = null;",
 "if (A.numKeys > 0) { for (var k = 1; k <= A.numKeys; k++) if (A.key(k).value <= 0.5) { tr = A.key(k).time; break; } }",
 "else if (A.value <= 0.5) tr = time;",
 "if (tr === null) { value; } else {",
 "  var r = sourceRectAtTime(time, false), r0 = sourceRectAtTime(tr, false);",
 "  var bil = effect(\"Bilateral push\")(1) > 0.5, dir = Math.round(effect(\"Stretch direction\")(1));",
 "  var dx = bil ? (r.left + r.width / 2) - (r0.left + r0.width / 2)",
 "         : (dir == 1 ? (r.left + r.width) - (r0.left + r0.width) : r.left - r0.left);",
 "  value.length > 2 ? [value[0] + dx, value[1], value[2]] : [value[0] + dx, value[1]];",
 "}"
].join("\n");

function dropdown(l, name, items, v) {
    var p = sqFx(l).property(name);
    if (p && p.matchName !== "ADBE Dropdown Control") { p.remove(); p = null; }
    if (!p) {
        p = sqFx(l).addProperty("ADBE Dropdown Control");
        p.name = name;
        try { sqFx(l).property(name).property(1).setPropertyParameters(items); } catch (e) {}
    }
    try { sqFx(l).property(name).property(1).setValue(v); } catch (e2) {}
    return sqFx(l).property(name);
}

var t0 = comp.time;
for (var i = 0; i < layers.length; i++) {
    var l = layers[i];
    if (!l.property("ADBE Text Properties")) { skipped++; continue; }
    var txt = String(l.property("ADBE Text Properties").property("ADBE Text Document").value.text);
    if (!/[ؠ-ي]/.test(txt)) { skipped++; continue; }
    sqRemoveFx(l, "SQ Kashida");            // v1-v3 controls
    sqSlider(l, "Stretch amount", 0);
    sqSlider(l, "Pivot", params.pivot);
    var dd = null;
    try { dd = dropdown(l, "Stretch direction", ["Left", "Right"], params.direction === "Right" ? 2 : 1); } catch (ed) { dd = null; }
    if (!dd) sqSlider(l, "Stretch direction", params.direction === "Right" ? 2 : 1);   // very old AE: 1 = Left, 2 = Right
    sqCheckbox(l, "Bilateral push", params.bilateral);

    var am = sqFx(l).property("Stretch amount").property(1);
    while (am.numKeys) am.removeKey(1);
    var N = Math.max(1, Math.round(params.amount || 6));
    if (params.animate) {
        // stretch in with a little overshoot, settle, (optionally) fold back before the layer ends
        var D = Math.max(0.1, params.duration || 0.6), B = (params.bounce || 0) / 100;
        am.setValueAtTime(t0, 0);
        if (B > 0.01) { am.setValueAtTime(t0 + D * 0.62, N * (1 + B * 0.6)); }
        am.setValueAtTime(t0 + D, N);
        if (params.collapse) {
            var te = Math.max(t0 + D + 0.2, l.outPoint - D * 0.8);
            am.setValueAtTime(te, N);
            am.setValueAtTime(Math.min(te + D * 0.8, l.outPoint), 0);
        }
        sqEaseKeys(am);
    } else {
        am.setValue(N);
    }
    l.property("ADBE Text Properties").property("ADBE Text Document").expression = expr;
    l.property("ADBE Transform Group").property("ADBE Anchor Point").expression = anchorExpr;
    n++;
}
if (!n) return "Select an Arabic text layer.";
return "Kashida Stretch on " + n + " layer" + (n > 1 ? "s" : "") + ". Tweak or keyframe \"Stretch amount\", \"Pivot\", direction and \"Bilateral push\" in Effect Controls." + (skipped ? " (" + skipped + " skipped, not Arabic text)" : "");

// Squeezy add-on: Arabic Write-On (host side). Runs as function(params, comp, layers).
// The panel drives it in phases:
//   phase "read"   selected Arabic text layer(s) -> AE outlines (Create Shapes from Text): returns every
//                  path in layer space + where it lives in the outlines layer (JSON string), then
//                  deletes the outlines again so nothing is left if the panel stops
//   phase "build"  gets back the pieces / marks / write paths the panel worked out, makes the outlines
//                  again (same paths, same order) and builds the rig in one undo step
//   phase "remove" deletes a Write-On's layers and shows the text again
if (!comp) throw new Error("Open a composition first.");
var TAG = "SQ Write";

function wq(s) { return String(s).replace(/\\/g, "\\\\").replace(/"/g, '\\"'); }
function wtr(l) { return l.property("ADBE Transform Group"); }
function isArabicText(l) {
    try { return /[\u0600-\u06FF\u0750-\u077F\uFB50-\uFDFF\uFE70-\uFEFF]/.test(String(l.property("ADBE Text Properties").property("ADBE Text Document").value.text)); } catch (e) { return false; }
}
// 2D affine [a, b, c, d, e, f]: x' = a x + c y + e, y' = b x + d y + f
function mMul(A, B) { return [A[0] * B[0] + A[2] * B[1], A[1] * B[0] + A[3] * B[1], A[0] * B[2] + A[2] * B[3], A[1] * B[2] + A[3] * B[3], A[0] * B[4] + A[2] * B[5] + A[4], A[1] * B[4] + A[3] * B[5] + A[5]]; }
function gMatrix(g) {
    var T = g.property("ADBE Vector Transform Group");
    var an = [0, 0], po = [0, 0], sc = [100, 100], ro = 0;
    try { an = T.property("ADBE Vector Anchor").value; } catch (e1) {}
    try { po = T.property("ADBE Vector Position").value; } catch (e2) {}
    try { sc = T.property("ADBE Vector Scale").value; } catch (e3) {}
    try { ro = T.property("ADBE Vector Rotation").value * Math.PI / 180; } catch (e4) {}
    var c = Math.cos(ro), s = Math.sin(ro), sx = sc[0] / 100, sy = sc[1] / 100;
    var M = [c * sx, s * sx, -s * sy, c * sy, 0, 0];
    M[4] = po[0] - (M[0] * an[0] + M[2] * an[1]); M[5] = po[1] - (M[1] * an[0] + M[3] * an[1]);
    return M;
}
function pt(M, p) { return [M[0] * p[0] + M[2] * p[1] + M[4], M[1] * p[0] + M[3] * p[1] + M[5]]; }
function vec(M, p) { return [M[0] * p[0] + M[2] * p[1], M[1] * p[0] + M[3] * p[1]]; }

// every path of a shape layer, with its index chain from the root (to find it again in a duplicate)
function walk(group, chain, M, out) {
    for (var i = 1; i <= group.numProperties; i++) {
        var it = group.property(i), mn = it.matchName, ch = chain.concat([i]);
        if (mn === "ADBE Vector Group") walk(it.property("ADBE Vectors Group"), ch.concat([2]), mMul(M, gMatrix(it)), out);
        else if (mn === "ADBE Vector Shape - Group") {
            var sh = it.property("ADBE Vector Shape").value, p = { ref: ch, v: [], i: [], o: [], c: sh.closed };
            for (var k = 0; k < sh.vertices.length; k++) { p.v.push(pt(M, sh.vertices[k])); p.i.push(vec(M, sh.inTangents[k])); p.o.push(vec(M, sh.outTangents[k])); }
            out.push(p);
        }
    }
}
function propAt(layer, chain) {
    var p = layer.property("ADBE Root Vectors Group");
    for (var i = 0; i < chain.length; i++) { if (!p) return null; p = p.property(chain[i]); }
    return p;
}
function chainKey(c) { return c.join("."); }
// keep only the listed paths in a duplicate of the outlines layer (empty groups go too)
function keepOnly(layer, keep) {
    var all = []; walk(layer.property("ADBE Root Vectors Group"), [], [1, 0, 0, 1, 0, 0], all);
    var k = {}; for (var i = 0; i < keep.length; i++) k[chainKey(keep[i])] = 1;
    var del = [];
    for (var j = 0; j < all.length; j++) if (!k[chainKey(all[j].ref)]) del.push(all[j].ref);
    // remove from the last index backwards so the earlier chains stay valid
    del.sort(function (a, b) { for (var q = 0; q < Math.max(a.length, b.length); q++) { var x = a[q] || 0, y = b[q] || 0; if (x !== y) return y - x; } return 0; });
