        var toB = function (d) { var j = 0; while (j < at.length - 2 && at[j + 1] < d) j++; var sp = at[j + 1] - at[j]; return Bc[j] + (Bc[j + 1] - Bc[j]) * (sp > 0 ? Math.min(1, Math.max(0, (d - at[j]) / sp)) : 0); };
        var LB = Bc[Bc.length - 1];
        // table rows: [ink so far, path so far], in units for now
        for (var q4 = 0; q4 < skips.length; q4++) {
            table.push([ftotal + F[skips[q4][0]], total + toB(cum[skips[q4][0]])]);
            table.push([ftotal + F[skips[q4][1]], total + toB(cum[skips[q4][1]])]);
        }
        S1.pts = sm; S1.cum = cum; S1.F = F; S1.len = LB; S1.ink = F[F.length - 1]; S1.base = ftotal;
        total += LB; ftotal += S1.ink;
    }
    table.push([ftotal, total]);
    for (var t1 = 0; t1 < table.length; t1++) table[t1] = [Math.round(table[t1][0] / Math.max(ftotal, 1e-9) * 1e4) / 1e4, Math.round(table[t1][1] / Math.max(total, 1e-9) * 1e4) / 1e4];
    return { strokes: strokes, masks: masks, brush: brush, len: total, ink: ftotal, remap: table.length > 2 ? table : null, raster: R };
};

// where along the piece (0..1) the pen passes closest to a point
WO.reach = function (tr, x, y) {
    var best = 1e18, at = 0;
    for (var s = 0; s < tr.strokes.length; s++) {
        var st = tr.strokes[s];
        for (var i = 0; i < st.pts.length; i++) {
            var dx = st.pts[i][0] - x, dy = st.pts[i][1] - y, d = dx * dx + dy * dy;
            if (d < best - 1e-9) { best = d; at = st.base + st.F[i]; }
        }
    }
    return { frac: tr.ink > 0 ? at / tr.ink : 0, dist: Math.sqrt(best) };
};

function r2(m) {
    function f(a) { return a.map(function (p) { return [Math.round(p[0] * 100) / 100, Math.round(p[1] * 100) / 100]; }); }
    return { v: f(m.v), i: f(m.i), o: f(m.o), c: false };
}
WO.plan = function (info, opt) {
    var dur = Math.max(0.1, opt.duration || 2), t0 = info.t0 || 0, fd = info.fd || 1 / 30, pct = (opt.brush || 100) / 100;
    function snap(t) { return Math.round(t / fd) * fd; }
    var L = [], total = 0, i, j;
    for (i = 0; i < info.layers.length; i++) {
        var lay = info.layers[i], em = lay.em > 0 ? lay.em : 100, cl = WO.classify(lay.paths, em), tr = [];
        if (!cl.pieces.length) continue;
        for (j = 0; j < cl.pieces.length; j++) { tr.push(WO.trace(cl.pieces[j], em, opt)); total += tr[j].ink; }
        L.push({ lay: lay, cl: cl, tr: tr, em: em });
    }
    if (!L.length) throw new Error("No letters found in the selected text.");
    var out = { layers: [] }, t = t0;
    for (i = 0; i < L.length; i++) {
        var o = { index: L[i].lay.index, name: L[i].lay.name, pieces: [], marks: [] }, times = [];
        for (j = 0; j < L[i].cl.pieces.length; j++) {
            var T = L[i].tr[j], d = Math.max(2 * fd, dur * (total > 0 ? T.ink / total : 1 / L[i].cl.pieces.length));
            var a = snap(t), b = Math.max(a + fd, snap(t + d)); times.push([a, b]); t += d;
            o.pieces.push({ refs: L[i].cl.pieces[j].refs, masks: T.masks.map(r2), remap: T.remap, brush: Math.round(T.brush * pct * 10) / 10, t0: a, t1: b });
        }
        // each mark pops when the stroke of the closest piece reaches it
        for (j = 0; j < L[i].cl.marks.length; j++) {
            var M = L[i].cl.marks[j], bi = 0, bd = 1e18, bf = 0;
            for (var p = 0; p < L[i].tr.length; p++) { var rc = WO.reach(L[i].tr[p], M.cx, M.cy); if (rc.dist < bd) { bd = rc.dist; bi = p; bf = rc.frac; } }
            var tm = snap(times[bi][0] + bf * (times[bi][1] - times[bi][0]));
            o.marks.push({ refs: M.refs, cx: M.cx, cy: M.cy, t: tm });
        }
        o.marks.sort(function (a, b) { return a.t - b.t; });
        out.layers.push(o);
    }
    return out;
};

WO._ = { raster: raster, edt: edt, thin: thin, prune: prune, nbrs: nbrs };
if (!api || !api.run) return WO;   // tests load the geometry only

var v = api.values || {};
if (v.action === "Remove") return api.run({ phase: "remove" });
var opt = { duration: parseFloat(String(v.duration).replace(",", ".")) || 2, brush: Number(v.brush) || 100, quality: 120 };
return api.run({ phase: "read" }).then(function (r) {
    if (!r.ok) return r;
    var data;
    try { data = WO.plan(JSON.parse(r.message), opt); }
    catch (e) { return api.run({ phase: "abort" }).then(function () { return { ok: false, error: "Write-On: " + (e.message || e) }; }); }
    return api.run({ phase: "build", data: data, bounce: !!v.bounce, pop: Number(v.pop) || 0.35 });
});

addons.script:
// ---- type checks that do not depend on instanceof ----
function sqIsComp(it) { try { if (it instanceof CompItem) return true; } catch (e) {} try { return !!it && typeof it.numLayers === "number" && typeof it.layers === "object"; } catch (e2) { return false; } }
function sqIsFolder(it) { try { if (it instanceof FolderItem) return true; } catch (e) {} try { return !!it && typeof it.numItems === "number" && typeof it.items === "object" && typeof it.numLayers !== "number"; } catch (e2) { return false; } }
function sqIsCamOrLight(L) { try { if (L.property("ADBE Camera Options Group") || L.property("ADBE Light Options Group")) return true; } catch (e) {} return false; }
// ---- Squeezy add-on helpers (ExtendScript, ES3) ----
function sqFx(l) { return l.property("ADBE Effect Parade"); }
function sqCtrl(l, match, name, v) {
    var p = sqFx(l).property(name);
    if (p && p.matchName !== match) { p.remove(); p = null; }
    if (!p) { p = sqFx(l).addProperty(match); p.name = name; p = sqFx(l).property(name); }
    try { if (v !== undefined && v !== null) p.property(1).setValue(v); } catch (e) {}
    return sqFx(l).property(name);
}
function sqSlider(l, name, v) { return sqCtrl(l, "ADBE Slider Control", name, v); }
function sqCheckbox(l, name, v) { return sqCtrl(l, "ADBE Checkbox Control", name, v ? 1 : 0); }
function sqHex(h) { var n = parseInt(String(h).replace("#", ""), 16); return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255, 1]; }
function sqRemoveFx(l, prefix) {
    var fx = sqFx(l); if (!fx) return;
    for (var i = fx.numProperties; i >= 1; i--) if (String(fx.property(i).name).indexOf(prefix) === 0) fx.property(i).remove();
}
function sqRemoveKids(comp, l, prefix) {
    for (var i = comp.numLayers; i >= 1; i--) {
        var c = comp.layer(i);
        if (c.parent && c.parent.index === l.index && String(c.name).indexOf(prefix) === 0) c.remove();
    }
}
function sqEaseKeys(prop) {
    for (var k = 1; k <= prop.numKeys; k++) {
        var dims = 1; try { var v = prop.keyValue(k); if (v instanceof Array) dims = v.length; } catch (e) {}
        if (prop.propertyValueType === PropertyValueType.TwoD_SPATIAL || prop.propertyValueType === PropertyValueType.ThreeD_SPATIAL) dims = 1;
        var a = [], b = [];
        for (var d = 0; d < dims; d++) { a.push(new KeyframeEase(0, 45)); b.push(new KeyframeEase(0, 45)); }
        try { prop.setTemporalEaseAtKey(k, a, b); } catch (e2) {}
    }
}

// ---- pixel grid reveal (used by Pixel Scan Reveal and Block Flow) ----
// Builds a block matte + optional glowing block layer, both parented to the target layer.
function sqScan(comp, l, o) {
    var r = l.sourceRectAtTime(o.t0, false);
    if (!r || r.width < 1 || r.height < 1) throw new Error(l.name + " has nothing visible at the current time");
    var size = Math.max(4, o.size), cols, rows;
    do { cols = Math.ceil(r.width / size); rows = Math.ceil(r.height / size); if (cols * rows > 700) size *= 1.15; } while (cols * rows > 700);

    sqRemoveKids(comp, l, "SQ Scan ");
    sqRemoveFx(l, "SQ Scan ");
    sqSlider(l, "SQ Scan Progress", 0);
    sqSlider(l, "SQ Scan Random", o.random);
    sqSlider(l, "SQ Scan Glow Band", o.band);
    var pr = sqFx(l).property("SQ Scan Progress").property(1);
    pr.setValueAtTime(o.t0, 0);
    pr.setValueAtTime(o.t0 + o.dur, 100);
    sqEaseKeys(pr);

    var cells = [];
    for (var y = 0; y < rows; y++) for (var x = 0; x < cols; x++) {
        var cx = r.left + (x + 0.5) * size, cy = r.top + (y + 0.5) * size, u;
        var nx = cols > 1 ? x / (cols - 1) : 0, ny = rows > 1 ? y / (rows - 1) : 0;
        switch (o.dir) {
            case "rtl": u = 1 - nx; break;
            case "ttb": u = ny; break;
            case "btt": u = 1 - ny; break;
            case "center": u = Math.min(1, Math.sqrt((nx - 0.5) * (nx - 0.5) + (ny - 0.5) * (ny - 0.5)) / 0.7072); break;
            case "random": u = Math.random(); break;
            default: u = nx;
        }
        cells.push({ x: cx, y: cy, u: u, q: Math.random() });
    }

    function grid(name, glow) {
        var s = comp.layers.addShape();
        s.name = name;
        s.moveBefore(l);
        s.parent = l;
        try { s.property("ADBE Transform Group").property("ADBE Anchor Point").setValue([0, 0]); } catch (e) {}
        try { s.property("ADBE Transform Group").property("ADBE Position").setValue([0, 0]); } catch (e1) { try { s.property("ADBE Transform Group").property("ADBE Position").setValue([0, 0, 0]); } catch (e2) {} }
        var root = function () { return s.property("ADBE Root Vectors Group"); };
        var bs = glow ? size * 0.78 : size + 1;
        var col = glow ? sqHex(o.color) : [1, 1, 1, 1];
        for (var i = 0; i < cells.length; i++) {
            var c = cells[i], k = (c.u * 1).toFixed(4), qq = c.q.toFixed(4);
            var gi = root().addProperty("ADBE Vector Group").propertyIndex;
            var G = function () { return root().property(gi); };
            G().property("ADBE Vectors Group").addProperty("ADBE Vector Shape - Rect");
            G().property("ADBE Vectors Group").property(1).property("ADBE Vector Rect Size").setValue([bs, bs]);
            G().property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Fill");
            G().property("ADBE Vectors Group").property(2).property("ADBE Vector Fill Color").setValue(col);
            var T = G().property("ADBE Vector Transform Group");
            T.property("ADBE Vector Position").setValue([c.x, c.y]);
            var head = "var P=parent.effect(\"SQ Scan Progress\")(1)/100, R=parent.effect(\"SQ Scan Random\")(1)/100; var k=" + k + "*(1-R)+" + qq + "*R*0.999;";
            G().property("ADBE Vector Transform Group").property("ADBE Vector Group Opacity").expression = glow
                ? head + " var B=Math.max(parent.effect(\"SQ Scan Glow Band\")(1)/100,0.001), d=P-k*(1-B)-B*0.5; (P>0 && P<1 && d>=-B*0.5 && d<B*0.5) ? 100*(1-Math.abs(d)/(B*0.5)) : 0;"
                : head + " (P>=1 || (P>0 && P>=k)) ? 100 : 0;";
        }
        return s;
    }

    var m = grid("SQ Scan Matte · " + l.name, false);
    if (o.glow) {
        var g = grid("SQ Scan Glow · " + l.name, true);
        g.blendingMode = BlendingMode.ADD;
        var gl = sqFx(g).addProperty("ADBE Glo2");
        try { gl.property(3).setValue(Math.max(10, size * 0.8)); gl.property(4).setValue(1.6); } catch (eg) {}
    }
    var done = false;
    try { if (l.setTrackMatte) { l.setTrackMatte(m, TrackMatteType.ALPHA); done = true; } } catch (et) {}
    if (!done) { m.moveBefore(l); l.trackMatteType = TrackMatteType.ALPHA; }
    m.enabled = false;
    return cells.length;
}

if (!comp) return "Open a composition first.";
var ls = [];
for (var i = 0; i < layers.length; i++) {
    var L0 = layers[i];
    if (!L0.property("ADBE Effect Parade") || sqIsCamOrLight(L0)) continue;
    if (String(L0.name).indexOf("SQ Cylinder") === 0) continue;
    ls.push(L0);
}
if (ls.length < 2) return "Select 2 or more layers for the cylinder.";
var n = ls.length, wsum = 0;
for (var a = 0; a < n; a++) {
    var r = ls[a].sourceRectAtTime(comp.time, false), sc = ls[a].property("ADBE Transform Group").property("ADBE Scale").value;
    wsum += r.width * sc[0] / 100;
}
var R = params.radius > 0 ? params.radius : Math.max(250, (wsum / n) * n * 1.15 / (2 * Math.PI));
var k = 1, nm;
do { nm = "SQ Cylinder " + k; k++; } while ((function () { for (var q = 1; q <= comp.numLayers; q++) if (comp.layer(q).name === nm) return true; return false; })());
var c = comp.layers.addNull();
c.name = nm; c.threeDLayer = true; c.label = 10;
c.property("ADBE Transform Group").property("ADBE Position").setValue([comp.width / 2, comp.height / 2, R]);
c.property("ADBE Transform Group").property("ADBE Rotate X").setValue(params.tilt);
sqSlider(c, "SQ Cyl Radius", R);
sqSlider(c, "SQ Cyl Angle", 0);
sqSlider(c, "SQ Cyl Spin", params.spin);
sqSlider(c, "SQ Cyl Back Blur", params.blur);
sqSlider(c, "SQ Cyl Back Opacity", params.minOpacity);
sqSlider(c, "SQ Cyl Back Darken", params.darken);
sqSlider(c, "SQ Cyl Focus", params.focus);
sqCheckbox(c, "SQ Cyl Snap To Cards", params.snap);
sqSlider(c, "SQ Cyl Hold", params.hold);
sqSlider(c, "SQ Cyl Count", n);

// placement: Angle slider + Spin, or step card-to-card when Snap is on
var head = [
 "var C=parent, R=C.effect(\"SQ Cyl Radius\")(1), N=Math.max(C.effect(\"SQ Cyl Count\")(1),1);",
 "var sp=C.effect(\"SQ Cyl Spin\")(1), rot;",
 "if (C.effect(\"SQ Cyl Snap To Cards\")(1)==1 && sp!=0) {",
 "  var st=360/N, mv=st/Math.abs(sp), hd=Math.max(C.effect(\"SQ Cyl Hold\")(1),0), cy=mv+hd, t=Math.max(time-C.inPoint,0);",
 "  var idx=Math.floor(t/cy), u=Math.min((t-idx*cy)/Math.max(mv,0.001),1); u=u<.5?4*u*u*u:1-Math.pow(-2*u+2,3)/2;",
 "  rot=(idx+u)*st*(sp>0?1:-1);",
 "} else rot=time*sp;",
 "var a=(C.effect(\"SQ Cyl Angle\")(1)+rot+"
].join("\n");

// depth: where this card really is, seen from the active camera (works with null rotation, camera moves, keyframes)
var depth = [
 "var C=parent, R=Math.max(C.effect(\"SQ Cyl Radius\")(1),1);",
 "var p=thisLayer.toWorld(thisLayer.anchorPoint), c=C.toWorld(C.anchorPoint), v=[0,0,1];",
 "try { var cam=thisComp.activeCamera; v=normalize(cam.toWorldVec([0,0,1])); } catch(e) {}",
 "var d=dot(sub(p,c),v)/R, f=clamp((d+1)/2,0,1);",                 // 0 = facing camera, 1 = far back
 "var F=clamp(C.effect(\"SQ Cyl Focus\")(1),0,100)/100, g=1-Math.pow(1-f, 1+F*5);"   // Focus: how fast the side cards fall off
].join("\n");

for (var j = 0; j < n; j++) {
    var l = ls[j], off = (j * 360 / n).toFixed(4);
    l.threeDLayer = true;
    l.parent = c;
    var T = l.property("ADBE Transform Group");
    var ang = head + off + ")*Math.PI/180;";
    T.property("ADBE Position").expression = ang + " [Math.sin(a)*R, 0, -Math.cos(a)*R];";
    T.property("ADBE Orientation").expression = ang + " lookAt([Math.sin(a)*R, 0, -Math.cos(a)*R], [0, 0, 0]);";
    T.property("ADBE Opacity").expression = depth + " value*(1 - g*(1-C.effect(\"SQ Cyl Back Opacity\")(1)/100));";
    sqRemoveFx(l, "SQ Cyl ");
    var b = sqFx(l).addProperty("ADBE Gaussian Blur 2"); b.name = "SQ Cyl Depth Blur";
    sqFx(l).property("SQ Cyl Depth Blur").property(1).expression = depth + " g*C.effect(\"SQ Cyl Back Blur\")(1);";
    try { sqFx(l).property("SQ Cyl Depth Blur").property(3).setValue(1); } catch (e) {}
    var s = sqFx(l).addProperty("ADBE Brightness & Contrast 2"); s.name = "SQ Cyl Depth Shade";
    sqFx(l).property("SQ Cyl Depth Shade").property(1).expression = depth + " -g*C.effect(\"SQ Cyl Back Darken\")(1);";
}
return "Cylinder with " + n + " cards. Depth, spin and snap live on \"" + nm + "\"";

// Squeezy add-on: Block Flow (ported from BlockFlow.jsx v1.4 by Kholy)
// runs as function(params, comp, layers)
var SCRIPT_NAME = "BlockFlow";
var VERSION = "1.4";

// ------------------------------------------------------------------
// helpers (ES3 safe)
// ------------------------------------------------------------------
function rr(x) { return x < 0 ? -Math.round(-x) : Math.round(x); }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }

function makeRng(seed) {
    var s = Math.abs(Math.floor(seed)) % 4294967296;
    if (s === 0) { s = 2463534242; }
    var r = function () {
        s = (s * 1664525 + 1013904223) % 4294967296;
        return s / 4294967296;
    };
    for (var i = 0; i < 8; i++) { r(); }
    return r;
}

// sort keys by time (stable), collapse duplicates keeping the last one written
function normKeys(keys) {
    var arr = [];
    for (var i = 0; i < keys.length; i++) { arr.push({ t: keys[i][0], v: keys[i][1], i: i }); }
    arr.sort(function (a, b) {
        if (Math.abs(a.t - b.t) < 1e-6) { return a.i - b.i; }
        return a.t - b.t;
    });
    var out = [];
    for (var j = 0; j < arr.length; j++) {
        if (out.length && Math.abs(out[out.length - 1][0] - arr[j].t) < 1e-6) {
            out[out.length - 1][1] = arr[j].v;
        } else {
            out.push([arr[j].t, arr[j].v]);
        }
    }
    return out;
}

// ------------------------------------------------------------------
// PLANNER  — pure maths, no AE calls. Decides every block and keyframe.
// ------------------------------------------------------------------
// Step-zoom profile measured from the reference: fraction of the interval
// after a change  →  share of that change's total (log) shrink.
var ZOOM_PROFILE = [[0, 0.72], [0.19, 0.216], [0.33, 0.032], [0.81, 0.032]];

// o.sizes = [[w,h], ...] one per card (already in comp pixels)
function buildPlan(n, o) {
    var rnd = makeRng(o.seed);
    var fps = o.fps, F = 1 / fps;
    function q(t) { return Math.round(t * fps) / fps; }

    var S = Math.max(1, Math.min(Math.round(o.slots), n));
    var pad = Math.max(0, Math.round(o.pad));
    var i, s, k;

    // ---- one block size for every card: "Grid columns" across an average card
    var sumW = 0;
    for (i = 0; i < n; i++) { sumW += o.sizes[i][0]; }
    var avgW = sumW / n;
    var cellPx = avgW / Math.max(1, Math.round(o.cols));

    // per-card grid geometry (each card keeps its own width × height)
    function geom(w, h) {
        var g = {};
        g.w = w; g.h = h;
        g.cols = Math.max(1, Math.round(w / cellPx));
        g.rows = Math.max(1, Math.round(h / cellPx));
        g.cellW = w / g.cols; g.cellH = h / g.rows;
        g.padX = rr(pad * g.cellW); g.padY = rr(pad * g.cellH);
        g.padW = w + 2 * g.padX; g.padH = h + 2 * g.padY;
        g.gCols = g.cols + 2 * pad; g.gRows = g.rows + 2 * pad;
        g.xE = function (x) { return g.padX + rr((x - pad) * g.cellW); };
        g.yE = function (y) { return g.padY + rr((y - pad) * g.cellH); };
        g.rect = function (gx, gy, gw, gh) {
            var x0 = g.xE(gx), y0 = g.yE(gy);
            return [x0, y0, g.xE(gx + gw) - x0, g.yE(gy + gh) - y0];
        };
        return g;
    }

    var D = Math.max(2 * F, q(o.trans));
    var I = Math.max(F, q(o.interval));
    var cycle = S * I;

    // ---- cards (one per image) & timing
    var cards = [];
    for (i = 0; i < n; i++) {
        cards.push({ index: i, slot: i % S, tIn: q(i * I), tOut: null,
                     start: 0, end: 0, cin: [], cout: [], g: geom(o.sizes[i][0], o.sizes[i][1]),
                     crisp: [], mosaic: [], accent: [], nx: 0, ny: 0,
                     scaleKeys: [], posKeys: [] });
    }
    for (i = 0; i < n; i++) {
        if (i + S < n) { cards[i].tOut = cards[i + S].tIn; }
        else if (o.exitAtEnd) { cards[i].tOut = q(cards[i].tIn + cycle + (o.holdEnd || 0)); }
    }
    var lastT = 0;
    for (i = 0; i < n; i++) {
        var e = (cards[i].tOut !== null) ? cards[i].tOut + D : cards[i].tIn + cycle + (o.holdEnd || 0);
        if (e > lastT) { lastT = e; }
    }
    var duration = q(lastT + (o.exitAtEnd ? 0.4 : 0));
    for (i = 0; i < n; i++) {
        cards[i].start = cards[i].tIn;
        cards[i].end = (cards[i].tOut !== null) ? Math.min(duration, q(cards[i].tOut + D + F)) : duration;
    }

    // ---- slot columns: spaced by the average width of the cards in each slot
    var cx = o.compW / 2, cy = o.compH / 2;
    var slotAvg = [];
    for (s = 0; s < S; s++) {
        var sw = 0, sc = 0;
        for (i = s; i < n; i += S) { sw += o.sizes[i][0]; sc++; }
        slotAvg.push(sw / sc);
    }
    var slotCX = [0];
    for (s = 1; s < S; s++) {
        // neighbours overlap by o.overlap of the narrower slot
        var ov = Math.min(slotAvg[s - 1], slotAvg[s]) * o.overlap;
        slotCX.push(slotCX[s - 1] + slotAvg[s - 1] / 2 + slotAvg[s] / 2 - ov);
    }
    var left = slotCX[0] - slotAvg[0] / 2, right = slotCX[S - 1] + slotAvg[S - 1] / 2;
    var shiftX = cx - (left + right) / 2;
    for (s = 0; s < S; s++) { slotCX[s] += shiftX; }

    // ---- global step zoom Z(t)
    var zsteps = [];
    if (o.zoomAmt > 0) {
        var total = Math.log(Math.max(0.05, 1 - o.zoomAmt));
        for (k = 1; k * I <= duration + 1e-6; k++) {
            for (var zp = 0; zp < ZOOM_PROFILE.length; zp++) {
                var zt = q(k * I + ZOOM_PROFILE[zp][0] * I);
                if (zt <= duration) { zsteps.push([zt, Math.exp(total * ZOOM_PROFILE[zp][1])]); }
            }
        }
    }
    function Z(t) {
        var z = 1;
        for (var a = 0; a < zsteps.length; a++) { if (zsteps[a][0] <= t + 1e-6) { z *= zsteps[a][1]; } }
        return z;
    }

    function sweepVal(dir, g, c, r) {
        var u = (c + 0.5) / g.cols, v = (r + 0.5) / g.rows;
        if (dir === 1) { return u; }
        if (dir === 2) { return 1 - u; }
        if (dir === 3) { return v; }
        return 1 - v;
    }

    function mosaicFlashes(card, T) {
        var g = card.g;
        var count = Math.round(o.mosaicAmt * g.cols * g.rows * 0.5);
        for (var m = 0; m < count; m++) {
            var gw = (rnd() < 0.7 || g.cols < 2) ? 1 : 2;
            var gh = (rnd() < 0.7 || g.rows < 2) ? 1 : 2;
            var gx, gy;
            if (rnd() < 0.85 || pad === 0) {
                gx = pad + Math.floor(rnd() * (g.cols - gw + 1));
                gy = pad + Math.floor(rnd() * (g.rows - gh + 1));
            } else {
                gx = clamp(pad - 1 + Math.floor(rnd() * (g.cols + 3 - gw)), 0, g.gCols - gw);
                gy = clamp(pad - 1 + Math.floor(rnd() * (g.rows + 3 - gh)), 0, g.gRows - gh);
            }
            var st = q(T + D * rnd() * 0.8);
            var en = q(st + (2 + Math.floor(rnd() * 4)) * F);
            card.mosaic.push({ r: g.rect(gx, gy, gw, gh), keys: [[card.start, 0], [st, 100], [en, 0]] });
        }
    }

    function accentFlashes(card, T) {
        var g = card.g;
        var count = Math.round(o.accentAmt * g.cols * g.rows * 0.35);
        for (var m = 0; m < count; m++) {
            var gw = Math.min(g.gCols, 1 + Math.floor(rnd() * 3));
            var gh = Math.min(g.gRows, 1 + Math.floor(rnd() * 3));
            var gx, gy;
            if (rnd() < 0.75) {
                gx = clamp(pad - 1 + Math.floor(rnd() * (g.cols + 3 - gw)), 0, g.gCols - gw);
                gy = clamp(pad - 1 + Math.floor(rnd() * (g.rows + 3 - gh)), 0, g.gRows - gh);
            } else {
                gx = Math.floor(rnd() * (g.gCols - gw + 1));
                gy = Math.floor(rnd() * (g.gRows - gh + 1));
            }
            var st = q(T + D * rnd() * 0.9);
            var en = q(st + (2 + Math.floor(rnd() * 6)) * F);
            card.accent.push({ r: g.rect(gx, gy, gw, gh), keys: [[card.start, 0], [st, 100], [en, 0]] });
        }
    }

    // ---- transition events per slot
    for (s = 0; s < S; s++) {
        var list = [];
        for (i = s; i < n; i += S) { list.push(i); }
        var events = [];
        for (k = 0; k < list.length; k++) {
            events.push({ T: cards[list[k]].tIn, inI: list[k], outI: (k > 0 ? list[k - 1] : -1) });
        }
        var lastC = list[list.length - 1];
        if (o.exitAtEnd && cards[lastC].tOut !== null) {
            events.push({ T: cards[lastC].tOut, inI: -1, outI: lastC });
        }

        for (var ev = 0; ev < events.length; ev++) {
            var E = events[ev], T = E.T;
            var dir = Math.floor(rnd() * 5); // 0 = pure random, 1-4 = soft sweep
            var pass = [];
            if (E.inI >= 0) { pass.push([cards[E.inI], true]); }
            if (E.outI >= 0) { pass.push([cards[E.outI], false]); }
            for (var ps = 0; ps < pass.length; ps++) {
                var cd0 = pass[ps][0], incoming = pass[ps][1], g0 = cd0.g;
                for (var r = 0; r < g0.rows; r++) {
                    for (var c = 0; c < g0.cols; c++) {
                        var sv = (dir === 0) ? rnd() : sweepVal(dir, g0, c, r);
                        var u = 0.55 * rnd() + 0.45 * sv;
                        if (incoming) { cd0.cin[r * g0.cols + c] = Math.max(q(T + D * (0.12 + 0.8 * u)), q(T + F)); }
                        else { cd0.cout[r * g0.cols + c] = q(T + D * 0.8 * u); }
                    }
                }
            }
            if (E.inI >= 0) { mosaicFlashes(cards[E.inI], T); accentFlashes(cards[E.inI], T); }
            if (E.outI >= 0) { mosaicFlashes(cards[E.outI], T); }
            if (E.inI < 0 && E.outI >= 0) { accentFlashes(cards[E.outI], T); }
        }
    }

    // ---- crisp cell masks + motion (scale/position) per card
    for (i = 0; i < n; i++) {
        var cd = cards[i], g = cd.g;
        for (var r2 = 0; r2 < g.rows; r2++) {
            for (var c2 = 0; c2 < g.cols; c2++) {
                var id = r2 * g.cols + c2;
                var a = cd.cin[id];
                var keys = [[cd.start, 0], [a, 100]];
                if (cd.cout[id] !== undefined) { keys.push([Math.max(cd.cout[id], q(a + F)), 0]); }
                cd.crisp.push({ r: g.rect(pad + c2, pad + r2, 1, 1), keys: keys });
            }
        }
        cd.cin = null; cd.cout = null;

        cd.nx = slotCX[cd.slot] + (o.jitter > 0 ? rr((rnd() * 2 - 1) * o.jitter) : 0);
        cd.ny = cy + (o.jitter > 0 ? rr((rnd() * 2 - 1) * o.jitter) : 0);

        var z0 = Z(cd.start);
        var times = [cd.start];
        for (k = 0; k < zsteps.length; k++) {
            if (zsteps[k][0] > cd.start + 1e-6 && zsteps[k][0] < cd.end - 1e-6) { times.push(zsteps[k][0]); }
        }
        for (k = 0; k < times.length; k++) {
            var rel = Z(times[k]) / z0;
            cd.scaleKeys.push([times[k], [100 * rel, 100 * rel]]);
            cd.posKeys.push([times[k], [cx + rel * (cd.nx - cx), cy + rel * (cd.ny - cy)]]);
        }

        // flatten geometry for the builder
        cd.w = g.w; cd.h = g.h; cd.padW = g.padW; cd.padH = g.padH; cd.padX = g.padX; cd.padY = g.padY;
        cd.mosaicH = g.gCols * o.mosaicDetail; cd.mosaicV = g.gRows * o.mosaicDetail;
        cd.cols = g.cols; cd.rows = g.rows;
        cd.g = null;
    }

    // ---- stacking order (bottom → top)
    var order = [];
    for (i = 0; i < n; i++) { order.push(i); }
    if (o.rightOnTop) {
        order.sort(function (x, y) {
            if (cards[x].slot !== cards[y].slot) { return cards[x].slot - cards[y].slot; }
            return x - y;
        });
    }

    return { duration: duration, fps: fps, S: S, cellPx: cellPx, cards: cards, order: order, zsteps: zsteps };
}

// ------------------------------------------------------------------
// AE BUILDER
// ------------------------------------------------------------------
function hexToRgb(h) {
    h = String(h).replace(/[^0-9a-fA-F]/g, "");
    if (h.length === 3) { h = h.charAt(0) + h.charAt(0) + h.charAt(1) + h.charAt(1) + h.charAt(2) + h.charAt(2); }
    if (h.length !== 6) { return [0, 0.82, 0.7]; }
    return [parseInt(h.substr(0, 2), 16) / 255, parseInt(h.substr(2, 2), 16) / 255, parseInt(h.substr(4, 2), 16) / 255];
}

function rectShape(r) {
    var sh = new Shape();
    sh.vertices = [[r[0], r[1]], [r[0] + r[2], r[1]], [r[0] + r[2], r[1] + r[3]], [r[0], r[1] + r[3]]];
    sh.closed = true;
    return sh;
}

function setHold(prop, keys) {
    keys = normKeys(keys);
    if (!keys.length) { return; }
    if (keys.length === 1) { prop.setValue(keys[0][1]); return; }
    var ts = [], vs = [];
    for (var i = 0; i < keys.length; i++) { ts.push(keys[i][0]); vs.push(keys[i][1]); }
    prop.setValuesAtTimes(ts, vs);
    for (var k = 1; k <= prop.numKeys; k++) {
        prop.setInterpolationTypeAtKey(k, KeyframeInterpolationType.HOLD, KeyframeInterpolationType.HOLD);
    }
}

function addRectMasks(layer, list) {
    var parade = layer.property("ADBE Mask Parade");
    for (var i = 0; i < list.length; i++) {
        var m = parade.addProperty("ADBE Mask Atom");
        m.maskMode = MaskMode.ADD;
        m.property("ADBE Mask Shape").setValue(rectShape(list[i].r));
        setHold(m.property("ADBE Mask Opacity"), list[i].keys);
    }
}

function natCmp(a, b) {
    var ax = String(a).toLowerCase().match(/(\d+|\D+)/g) || [];
    var bx = String(b).toLowerCase().match(/(\d+|\D+)/g) || [];
    while (ax.length && bx.length) {
        var x = ax.shift(), y = bx.shift();
        var nx = /^\d/.test(x), ny = /^\d/.test(y);
        if (nx && ny) { var d = parseInt(x, 10) - parseInt(y, 10); if (d) { return d; } }
        else if (x !== y) { return x < y ? -1 : 1; }
    }
    return ax.length - bx.length;
}

function isCompItem(it) {
    try { if (it instanceof CompItem) { return true; } } catch (e) {}
    try { return it && typeof it.numLayers === "number" && typeof it.layers === "object"; } catch (e2) { return false; }
}
function isUsableSource(it) {
    if (!it) { return false; }
    if (isCompItem(it)) { return true; }
    var ms = null;
    try { ms = it.mainSource; } catch (e) { ms = null; }
    if (!ms) { return false; }
    try { if (ms.color !== undefined && ms.file === undefined) { return false; } } catch (e2) {}   // solid
    return it.width > 0 && it.height > 0;
}

// images/comps selected in the Project panel (sorted by name)
function getProjectItems() {
    var out = [];
    var sel = app.project.selection;
    for (var i = 0; i < sel.length; i++) { if (isUsableSource(sel[i])) { out.push(sel[i]); } }
    out.sort(function (a, b) { return natCmp(a.name, b.name); });
    return out;
}

// selected layers in a comp → their sources. Layers without a usable source
// (text, shape, solid…) are precomposed first. Returns items + the layers to hide
// + the top-most layer (new cards are stacked right above it).
// layer filter without instanceof (more reliable when run from the Squeezy panel)
function cardSkipReason(L) {
    try { if (L.property("ADBE Camera Options Group")) { return "camera"; } } catch (e1) {}
    try { if (L.property("ADBE Light Options Group")) { return "light"; } } catch (e2) {}
    try { if (L.nullLayer) { return "null"; } } catch (e3) {}
    try { if (L.adjustmentLayer) { return "adjustment layer"; } } catch (e4) {}
    try { if (!L.property("ADBE Transform Group")) { return "no transform"; } } catch (e5) { return "unreadable"; }
    return "";
}

function resolveLayers(comp, reverse, given) {
    var sel = (given && given.length) ? given : comp.selectedLayers, arr = [], i, skipped = [];
    for (i = 0; i < sel.length; i++) { arr.push(sel[i]); }
    arr.sort(function (a, b) { return a.index - b.index; });
    if (reverse) { arr.reverse(); }
    var items = [], layers = [];
    for (i = 0; i < arr.length; i++) {
        var L = arr[i];
        var why = cardSkipReason(L);
        if (why) { skipped.push(L.name + " (" + why + ")"); continue; }
        if (!(L.source && isUsableSource(L.source))) {
            var idx = L.index, nm = L.name;
            comp.layers.precompose([idx], "BF src – " + nm, true);
            L = comp.layer(idx);
            cropToContent(L, comp.time);
        }
        items.push(L.source);
        layers.push(L);
    }
    if (!layers.length) { throw new Error("None of the selected layers can be used: " + (skipped.length ? skipped.join(", ") : "nothing selected")); }
    var top = layers[0];
    for (i = 1; i < layers.length; i++) { if (layers[i].index < top.index) { top = layers[i]; } }
    return { items: items, layers: layers, top: top };
}

// A shape/text layer just precomposed sits in a comp-sized precomp. Shrink that
// precomp to the shape's own bounds so the card hugs the shape, and keep the
// outer layer exactly where it was on screen.
function cropToContent(outer, time) {
    try {
        var tt = time - outer.startTime, nc = outer.source, minX = 1e9, minY = 1e9, maxX = -1e9, maxY = -1e9, j;
        var inner = [];
        for (j = 1; j <= nc.numLayers; j++) { inner.push(nc.layer(j)); }
        for (j = 0; j < inner.length; j++) {
            var Ly = inner[j];
            if (!Ly.enabled || cardSkipReason(Ly)) { continue; }
            var r = Ly.sourceRectAtTime(tt, false);
            var tg = Ly.property("ADBE Transform Group");
            var ap = tg.property("ADBE Anchor Point").valueAtTime(tt, false);
            var ps = tg.property("ADBE Position").valueAtTime(tt, false);
            var sc = tg.property("ADBE Scale").valueAtTime(tt, false);
            var rot = 0;
            try { rot = tg.property("ADBE Rotate Z").valueAtTime(tt, false); } catch (eR) {}
            var cs = Math.cos(rot * Math.PI / 180), sn = Math.sin(rot * Math.PI / 180);
            var corners = [[r.left, r.top], [r.left + r.width, r.top], [r.left, r.top + r.height], [r.left + r.width, r.top + r.height]];
            for (var k = 0; k < 4; k++) {
                var vx = (corners[k][0] - ap[0]) * sc[0] / 100, vy = (corners[k][1] - ap[1]) * sc[1] / 100;
                var x = ps[0] + vx * cs - vy * sn, y = ps[1] + vx * sn + vy * cs;
                if (x < minX) { minX = x; } if (x > maxX) { maxX = x; }
                if (y < minY) { minY = y; } if (y > maxY) { maxY = y; }
            }
        }
        if (maxX <= minX || maxY <= minY) { return; }
        var m = 4; // small margin for anti-aliasing / strokes
        minX = Math.floor(minX - m); minY = Math.floor(minY - m);
        var w = Math.ceil(maxX + m) - minX, h = Math.ceil(maxY + m) - minY;
        w = clamp(w, 4, 30000); h = clamp(h, 4, 30000);
        nc.width = w; nc.height = h;
        for (j = 0; j < inner.length; j++) {
            var pp = inner[j].property("ADBE Transform Group").property("ADBE Position");
            if (pp.numKeys > 0) {
                for (var kk = 1; kk <= pp.numKeys; kk++) {
                    var kv = pp.keyValue(kk);
                    pp.setValueAtKey(kk, kv.length > 2 ? [kv[0] - minX, kv[1] - minY, kv[2]] : [kv[0] - minX, kv[1] - minY]);
                }
            } else if (!pp.expressionEnabled) {
                var pv = pp.value;
                pp.setValue(pv.length > 2 ? [pv[0] - minX, pv[1] - minY, pv[2]] : [pv[0] - minX, pv[1] - minY]);
            }
        }
        var otg = outer.property("ADBE Transform Group");
        otg.property("ADBE Anchor Point").setValue([w / 2, h / 2]);
        otg.property("ADBE Position").setValue([minX + w / 2, minY + h / 2]);
    } catch (e) { /* keep the full-comp precomp if anything fails */ }
}

// size of every card in comp pixels
//   fixed size  → the typed W × H
//   layers mode → source size × the layer's current scale (what you see in the comp)
//   project mode → source size
// then × Card scale %
function cardSizes(items, layers, o, time) {
    var out = [];
    for (var i = 0; i < items.length; i++) {
        var w, h;
        if (o.fixedSize) { w = o.fixedW; h = o.fixedH; }
        else {
            w = items[i].width * items[i].pixelAspect / o.pa;
            h = items[i].height;
            if (layers && layers[i]) {
                var sv = [100, 100];
                try { sv = layers[i].property("ADBE Transform Group").property("ADBE Scale").valueAtTime(time, false); } catch (e) {}
                w *= Math.abs(sv[0]) / 100;
                h *= Math.abs(sv[1]) / 100;
            }
        }
        out.push([Math.max(8, Math.round(w * o.cardScale)), Math.max(8, Math.round(h * o.cardScale))]);
    }
    return out;
}

function itemHasAlpha(it) {
    if (isCompItem(it)) { return true; }
    try { return !!it.mainSource.hasAlpha; } catch (e) { return false; }
}

function setEffectParam(fx, index, englishName, value) {
    var p = null;
    try { p = fx.property(englishName); } catch (e1) { p = null; }
    if (!p) { try { p = fx.property(index); } catch (e2) { p = null; } }
    if (p) { try { p.setValue(value); } catch (e3) {} }
}

function build(items, o, progress) {
    var n = items.length;
    var plan = buildPlan(n, o);
    var pa = o.pa, fps = o.fps, dur = plan.duration;
    var accent = hexToRgb(o.accentHex);

    var stamp = 1;
    for (var p = 1; p <= app.project.numItems; p++) {
        var mm = app.project.item(p).name.match(/^BlockFlow (\d+)$/);
        if (mm && (function (x) { try { return x instanceof FolderItem || typeof x.numItems === "number"; } catch (e) { return false; } })(app.project.item(p))) { stamp = Math.max(stamp, parseInt(mm[1], 10) + 1); }
    }
    var folder = app.project.items.addFolder("BlockFlow " + stamp);
    var pre = app.project.items.addFolder("BF precomps " + stamp);
    pre.parentFolder = folder;

    var totalSteps = n * 2 + 1, step = 0;
    function tick(msg) { step++; if (progress) { progress(step / totalSteps, msg); } }

    // ---- per-card comps: clean image, mosaic version, and the masked card
    var cardComps = [], i;
    for (i = 0; i < n; i++) {
        var it = items[i], cd = plan.cards[i];

        // clean image: cover-fit to the card, edges extended for spill blocks
        var ic = app.project.items.addComp("BF img " + (i + 1) + " – " + it.name, cd.padW, cd.padH, pa, dur, fps);
        ic.parentFolder = pre;
        var alpha = itemHasAlpha(it);
        var L = ic.layers.add(it);
        var ew = it.width * it.pixelAspect / pa, eh = it.height;
        if (o.fixedSize) {
            // fixed card size: cover-fit (crop, never stretch)
            var sc = Math.max(cd.w / ew, cd.h / eh) * 100;
            L.property("ADBE Transform Group").property("ADBE Scale").setValue([sc, sc]);
        } else {
            // card = the layer's own size: exact fit (keeps non-uniform layer scale too)
            L.property("ADBE Transform Group").property("ADBE Scale").setValue([cd.w / ew * 100, cd.h / eh * 100]);
        }
        L.property("ADBE Transform Group").property("ADBE Position").setValue([cd.padW / 2, cd.padH / 2]);
        if (!alpha) {
            try {
                var mt = L.property("ADBE Effect Parade").addProperty("ADBE Tile");
                setEffectParam(mt, 4, "Output Width", 400);
                setEffectParam(mt, 5, "Output Height", 400);
                setEffectParam(mt, 6, "Mirror Edges", 1);
            } catch (eTile) {}
        }

        // mosaic version
        var mc = app.project.items.addComp("BF mosaic " + (i + 1), cd.padW, cd.padH, pa, dur, fps);
        mc.parentFolder = pre;
        var ML = mc.layers.add(ic);
        var mo = ML.property("ADBE Effect Parade").addProperty("ADBE Mosaic");
        setEffectParam(mo, 1, "Horizontal Blocks", cd.mosaicH);
        setEffectParam(mo, 2, "Vertical Blocks", cd.mosaicV);
        tick("Image " + (i + 1));

        // card comp: crisp cells (bottom), mosaic flashes, accent blocks (top)
        var cc = app.project.items.addComp("BF card " + (i + 1), cd.padW, cd.padH, pa, dur, fps);
        cc.parentFolder = pre;
        var lay = cc.layers.add(ic);
        lay.startTime = cd.start;
        lay.name = "image";
        addRectMasks(lay, cd.crisp);
        if (cd.mosaic.length) {
            lay = cc.layers.add(mc);
            lay.startTime = cd.start;
            lay.name = "pixel blocks";
            addRectMasks(lay, cd.mosaic);
        }
        if (cd.accent.length) {
            var ac = cc.layers.addSolid(accent, "Accent blocks", cd.padW, cd.padH, pa, dur);
            addRectMasks(ac, cd.accent);
        }
        if (o.clipToShape) {
            // Stencil Alpha on top cuts every block (pixel + accent) to the layer itself:
            //  - transparent shapes / PNGs → the shape's own alpha
            //  - solid images              → the card rectangle
            var stl;
            if (alpha) {
                stl = cc.layers.add(ic);
            } else {
                stl = cc.layers.addSolid([1, 1, 1], "stencil", cd.padW, cd.padH, pa, dur);
                addRectMasks(stl, [{ r: [cd.padX, cd.padY, cd.w, cd.h], keys: [[0, 100]] }]);
            }
            stl.startTime = 0;
            stl.name = "shape stencil";
            stl.blendingMode = BlendingMode.STENCIL_ALPHA;
        }
        cardComps.push(cc);
        tick("Card " + (i + 1));
    }

    // ---- host comp: the user's comp (layers mode) or a new one (project mode)
    var host, t0 = 0, created = [];
    if (o.inPlace) {
        host = o.inPlace.comp;
        t0 = Math.round(host.time * fps) / fps;
        if (t0 + dur > host.duration) { host.duration = t0 + dur; o.extended = true; }
    } else {
        host = app.project.items.addComp("BlockFlow " + stamp, o.compW, o.compH, pa, dur, fps);
        host.parentFolder = folder;
    }
    function shift(keys) {
        var out = [];
        for (var a = 0; a < keys.length; a++) { out.push([keys[a][0] + t0, keys[a][1]]); }
        return out;
    }
    for (var oi = 0; oi < plan.order.length; oi++) {
        var c = plan.cards[plan.order[oi]];
        var CL = host.layers.add(cardComps[c.index]);
        CL.name = "BF Card " + (c.index + 1) + " – " + items[c.index].name;
        CL.startTime = t0;
        CL.inPoint = t0 + c.start;
        CL.outPoint = t0 + Math.max(c.end, c.start + 1 / fps);
        var tg = CL.property("ADBE Transform Group");
        setHold(tg.property("ADBE Scale"), shift(c.scaleKeys));
        setHold(tg.property("ADBE Position"), shift(c.posKeys));
        created.push(CL);
    }
    tick("Cards placed");

    if (o.inPlace) {
        // stack the new layers right above the top-most selected layer (keeps their order)
        var ref = o.inPlace.top;
        for (var ci = created.length - 1; ci >= 0; ci--) {
            try { created[ci].moveBefore(ref); } catch (eMv) {}
        }
        if (o.hideOriginals) {
            for (var hi = 0; hi < o.inPlace.layers.length; hi++) {
                try { o.inPlace.layers[hi].enabled = false; } catch (eH) {}
            }
        }
        for (var si = 1; si <= host.numLayers; si++) { host.layer(si).selected = false; }
        for (si = 0; si < created.length; si++) { created[si].selected = true; }
    } else {
        host.openInViewer();
    }
    return host;
}


// ------------------------------------------------------------------
// Squeezy entry point (replaces the ScriptUI panel)
// ------------------------------------------------------------------
function P(k, d) { var v = params[k]; return (v === undefined || v === null || v === "") ? d : v; }
function N(k, d) { var v = parseFloat(P(k, d)); return isNaN(v) ? d : v; }
var target = comp || null;
var layerMode = !!(target && layers.length > 0);
var items = layerMode ? null : getProjectItems();
if (!layerMode && items.length < 1) {
    return "Select the layers you want in your comp (or images in the Project panel), then press Build.";
}
var o = {};
if (layerMode) { o.compW = target.width; o.compH = target.height; o.fps = target.frameRate; }
else { o.compW = target ? target.width : 1920; o.compH = target ? target.height : 1080; o.fps = target ? target.frameRate : 25; }
o.pa = target ? target.pixelAspect : 1;
o.slots = Math.max(1, Math.round(N("slots", 2)));
o.overlap = clamp(N("overlap", 12), 0, 90) / 100;
var fw = parseFloat(P("cardW", "layer")), fh = parseFloat(P("cardH", "layer"));
o.fixedSize = !isNaN(fw) && !isNaN(fh) && fw > 0 && fh > 0;
o.fixedW = o.fixedSize ? Math.round(fw) : 0; o.fixedH = o.fixedSize ? Math.round(fh) : 0;
o.cardScale = Math.max(1, N("cardScale", 100)) / 100;
o.cols = clamp(Math.round(N("cols", 8)), 1, 40);
o.pad = clamp(Math.round(N("pad", 2)), 0, 6);
o.interval = Math.max(0.04, N("interval", 0.85));
o.trans = Math.max(0.08, N("trans", 0.5));
o.zoomAmt = clamp(N("zoomAmt", 27), 0, 90) / 100;
o.seed = Math.round(N("seed", 7));
o.accentHex = String(P("accentHex", "#00D2B4"));
o.accentAmt = clamp(N("accentAmt", 35), 0, 100) / 100;
o.mosaicAmt = clamp(N("mosaicAmt", 40), 0, 100) / 100;
o.mosaicDetail = clamp(Math.round(N("mosaicDetail", 2)), 1, 6);
o.jitter = Math.max(0, N("jitter", 14));
o.holdEnd = Math.max(0, N("holdEnd", 1));
o.clipToShape = !!params.clipToShape;
o.exitAtEnd = !!params.exitAtEnd;
o.rightOnTop = !!params.rightOnTop;
o.hideOriginals = !!params.hideOriginals;
o.reverseOrder = !!params.reverseOrder;
o.inPlace = null;

var t0 = new Date().getTime();
if (layerMode) {
    var res = resolveLayers(target, o.reverseOrder, layers);
    items = res.items;
    o.inPlace = { comp: target, layers: res.layers, top: res.top };
}
o.sizes = cardSizes(items, layerMode ? o.inPlace.layers : null, o, layerMode ? target.time : 0);
var host = build(items, o, null);
var secs = Math.round((new Date().getTime() - t0) / 100) / 10;
return (layerMode
    ? "Block Flow: " + items.length + " cards from the playhead (" + secs + "s)"
    : "Block Flow: new comp \"" + host.name + "\" from " + items.length + " images (" + secs + "s)")
    + (o.extended ? ". Comp was lengthened to fit." : "");

// Squeezy add-on: Pixel Scan Reveal (ported from PixelScan_Reveal v1.0 by Kholy)
// runs as function(params, comp, layers)
// ---- type checks that do not depend on instanceof ----
function sqIsComp(it) { try { if (it instanceof CompItem) return true; } catch (e) {} try { return !!it && typeof it.numLayers === "number" && typeof it.layers === "object"; } catch (e2) { return false; } }
function sqIsFolder(it) { try { if (it instanceof FolderItem) return true; } catch (e) {} try { return !!it && typeof it.numItems === "number" && typeof it.items === "object" && typeof it.numLayers !== "number"; } catch (e2) { return false; } }
function sqIsCamOrLight(L) { try { if (L.property("ADBE Camera Options Group") || L.property("ADBE Light Options Group")) return true; } catch (e) {} return false; }
var SCRIPT_NAME = "Pixel Scan Reveal";
var VERSION = "1.0";
var TAG = "PixelScanRig";
var FOLDER_NAME = "PixelScan Precomps";

// ------------------------------------------------------------------
//  Small helpers
// ------------------------------------------------------------------

function esc(s) {
    return String(s).replace(/\\/g, "\\\\").replace(/"/g, "\\\"");
}

function trimStr(s) {
    return String(s).replace(/^\s+|\s+$/g, "");
}

function shortName(s) {
    s = trimStr(String(s));
    if (s.length > 24) { s = s.substring(0, 24); }
    return s;
}

function makeId() {
    var chars = "abcdefghjkmnpqrstuvwxyz23456789";
    var out = "";
    for (var i = 0; i < 4; i++) {
        out += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return out;
}

function tagString(id, role) {
    return TAG + ":" + id + ":" + role;
}

function readTag(str) {
    var m = String(str || "").match(/PixelScanRig:([a-z0-9]+):([a-zA-Z]+)/);
    if (!m) { return null; }
    return { id: m[1], role: m[2] };
}

// Find a property by a list of names / matchNames (direct first, then deep search)
function findProp(group, keys) {
    if (!group) { return null; }
    var i, p;
    for (i = 0; i < keys.length; i++) {
        try {
            p = group.property(keys[i]);
            if (p) { return p; }
        } catch (e) {}
    }
    for (i = 0; i < keys.length; i++) {
        p = deepFind(group, keys[i], 0);
        if (p) { return p; }
    }
    return null;
}

function deepFind(group, key, depth) {
    if (depth > 4) { return null; }
    var n = 0;
    try { n = group.numProperties; } catch (e) { return null; }
    for (var i = 1; i <= n; i++) {
        var p = null;
        try { p = group.property(i); } catch (e2) { p = null; }
        if (!p) { continue; }
        if (p.name === key || p.matchName === key) { return p; }
        if (p.propertyType === PropertyType.NAMED_GROUP || p.propertyType === PropertyType.INDEXED_GROUP) {
            var r = deepFind(p, key, depth + 1);
            if (r) { return r; }
        }
    }
    return null;
}

function setVal(group, keys, v) {
    var p = findProp(group, keys);
    if (!p) { return false; }
    try { p.setValue(v); return true; } catch (e) { return false; }
}

function setExpr(group, keys, expr) {
    var p = findProp(group, keys);
    if (!p) { return false; }
    try { p.expression = expr; return true; } catch (e) { return false; }
}

function setColor(prop, rgb) {
    if (!prop) { return; }
    try { prop.setValue([rgb[0], rgb[1], rgb[2], 1]); }
    catch (e) {
        try { prop.setValue([rgb[0], rgb[1], rgb[2]]); } catch (e2) {}
    }
}

function addFx(layer, matchName, name) {
    var parade = layer.property("ADBE Effect Parade");
    if (!parade.canAddProperty(matchName)) { return null; }
    var fx = parade.addProperty(matchName);
    if (name) {
        try { fx.name = name; } catch (e) {}
    }
    return fx;
}

function addCtrl(layer, type, name, value) {
    var matchName = {
        slider:   "ADBE Slider Control",
        angle:    "ADBE Angle Control",
        color:    "ADBE Color Control",
        checkbox: "ADBE Checkbox Control"
    }[type];
    var fx = addFx(layer, matchName, name);
    if (!fx) { return; }
    if (type === "color") { setColor(fx.property(1), value); }
    else { try { fx.property(1).setValue(value); } catch (e) {} }
}

function hexToRgb(hex) {
    hex = String(hex).replace(/[^0-9a-fA-F]/g, "");
    if (hex.length === 3) {
        hex = hex.charAt(0) + hex.charAt(0) + hex.charAt(1) + hex.charAt(1) + hex.charAt(2) + hex.charAt(2);
    }
    if (hex.length !== 6) { return null; }
    var n = parseInt(hex, 16);
    return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

function intToHex(n) {
    var s = (n & 0xFFFFFF).toString(16).toUpperCase();
    while (s.length < 6) { s = "0" + s; }
    return "#" + s;
}

function getFolder() {
    for (var i = 1; i <= app.project.numItems; i++) {
        var it = app.project.item(i);
        if (sqIsFolder(it) && it.name === FOLDER_NAME) { return it; }
    }
    return app.project.items.addFolder(FOLDER_NAME);
}

function hasTrackMatteSafe(layer) {
    try { return layer.hasTrackMatte === true; } catch (e) { return false; }
}

function setMatte(layer, matte) {
    if (typeof layer.setTrackMatte === "function") {
        // AE 2023+ : matte can be anywhere in the stack
        layer.setTrackMatte(matte, TrackMatteType.ALPHA);
        try { matte.enabled = false; } catch (e) {}
    } else {
        // Legacy: matte must sit directly above
        matte.moveBefore(layer);
        layer.trackMatteType = TrackMatteType.ALPHA;
    }
}

// ------------------------------------------------------------------
//  Expressions
// ------------------------------------------------------------------

// Position of the wipe group (moves the frontier along the chosen direction)
function exprFrontierPos(ref) {
    return [
        "var C = " + ref + ";",
        "var p = C.effect(\"Progress\")(1);",
        "var d = degreesToRadians(C.effect(\"Direction\")(1));",
        "var u = [Math.sin(d), -Math.cos(d)];",
        "var w = thisComp.width, h = thisComp.height;",
        "var E = (w * Math.abs(u[0]) + h * Math.abs(u[1])) / 2;",
        "var M = Math.abs(C.effect(\"Distortion\")(1)) * 0.5 + Math.abs(C.effect(\"Block Size\")(1)) + Math.abs(C.effect(\"Scan Width\")(1)) * 0.5;",
        "var s = linear(p, 0, 100, -E - M, E + M);",
        "[u[0] * s, u[1] * s];"
    ].join("\n");
}

function exprRotation(ref) {
    return ref + ".effect(\"Direction\")(1) - 90;";
}

function exprBandSize(ref, big) {
    return "[Math.max(1, " + ref + ".effect(\"Scan Width\")(1)), " + big + "];";
}

function exprBlocks(ref, axis) {
    var dim = (axis === "h") ? "thisComp.width" : "thisComp.height";
    return "Math.max(1, Math.round(" + dim + " / Math.max(2, " + ref + ".effect(\"Block Size\")(1))));";
}

// ------------------------------------------------------------------
//  Builders
// ------------------------------------------------------------------

// Comp-aligned shape layer holding one rectangle inside a group "Wipe".
// rectSize may be an array or an expression string.
function makeRectShape(comp, name, rectSize, rectPos) {
    var sl = comp.layers.addShape();
    sl.name = name;
    var tr = sl.property("ADBE Transform Group");
    tr.property("ADBE Anchor Point").setValue([0, 0]);
    tr.property("ADBE Position").setValue([comp.width / 2, comp.height / 2]);

    sl.property("ADBE Root Vectors Group").addProperty("ADBE Vector Group");
    var grp = sl.property("ADBE Root Vectors Group").property(1);
    grp.name = "Wipe";

    grp.property("ADBE Vectors Group").addProperty("ADBE Vector Shape - Rect");
    var rect = sl.property("ADBE Root Vectors Group").property(1).property("ADBE Vectors Group").property(1);
    rect.property("ADBE Vector Rect Position").setValue(rectPos);
    if (typeof rectSize === "string") {
        rect.property("ADBE Vector Rect Size").expression = rectSize;
    } else {
        rect.property("ADBE Vector Rect Size").setValue(rectSize);
    }

    sl.property("ADBE Root Vectors Group").property(1).property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Fill");
    var fill = sl.property("ADBE Root Vectors Group").property(1).property("ADBE Vectors Group").property(2);
    setColor(fill.property("ADBE Vector Fill Color"), [1, 1, 1]);

    return sl;
}

function wireWipe(sl, ref) {
    var gtr = sl.property("ADBE Root Vectors Group").property(1).property("ADBE Vector Transform Group");
    gtr.property("ADBE Vector Position").expression = exprFrontierPos(ref);
    gtr.property("ADBE Vector Rotation").expression = exprRotation(ref);
}

// Turbulent Displace + Mosaic: the jagged pixel edge (same settings on both mattes
// so the scan strip sits exactly on the reveal frontier)
function addMatteFx(sl, ref) {
    var td = addFx(sl, "ADBE Turbulent Displace", "PS Turbulence");
    if (td) {
        setExpr(td, ["Amount", "ADBE Turbulent Displace-0002"], ref + ".effect(\"Distortion\")(1);");
        setExpr(td, ["Size", "ADBE Turbulent Displace-0003"], ref + ".effect(\"Distortion Size\")(1);");
        setVal(td, ["Complexity", "ADBE Turbulent Displace-0005"], 8);
        setExpr(td, ["Evolution", "ADBE Turbulent Displace-0006"], ref + ".effect(\"Evolution\")(1);");
    }
    var mo = addFx(sl, "ADBE Mosaic", "PS Mosaic");
    if (mo) {
        setExpr(mo, ["Horizontal Blocks", "ADBE Mosaic-0001"], exprBlocks(ref, "h"));
        setExpr(mo, ["Vertical Blocks", "ADBE Mosaic-0002"], exprBlocks(ref, "v"));
        setExpr(mo, ["Sharp Colors", "ADBE Mosaic-0003"], ref + ".effect(\"Sharp Blocks\")(1);");
    }
}

function buildController(comp, name, id, o) {
    var ctrl = comp.layers.addNull(comp.duration);
    ctrl.name = name;
    ctrl.comment = tagString(id, "ctrl");
    try { ctrl.label = 2; } catch (e) {}

    addCtrl(ctrl, "slider",   "Progress",        o.out ? 100 : 0);
    addCtrl(ctrl, "angle",    "Direction",       o.direction);
    addCtrl(ctrl, "slider",   "Block Size",      o.blockSize);
    addCtrl(ctrl, "slider",   "Scan Width",      o.scanWidth);
    addCtrl(ctrl, "slider",   "Distortion",      200);
    addCtrl(ctrl, "slider",   "Distortion Size", 80);
    addCtrl(ctrl, "angle",    "Evolution",       0);
    addCtrl(ctrl, "checkbox", "Sharp Blocks",    0);
    addCtrl(ctrl, "color",    "Scan Color",      o.color);
    addCtrl(ctrl, "slider",   "Rainbow",         o.rainbow);
    addCtrl(ctrl, "angle",    "Hue Shift",       0);
    addCtrl(ctrl, "slider",   "Smear",           200);
    addCtrl(ctrl, "slider",   "Glass Depth",     200);
    addCtrl(ctrl, "slider",   "Glow Intensity",  100);
    addCtrl(ctrl, "slider",   "Glow Size",       100);
    addCtrl(ctrl, "slider",   "Scan Opacity",    100);

    // Animate Progress from the current time
    var prog = ctrl.property("ADBE Effect Parade").property("Progress").property(1);
    var t0 = comp.time;
    var t1 = t0 + Math.max(comp.frameDuration, o.duration);
    prog.setValueAtTime(t0, o.out ? 100 : 0);
    prog.setValueAtTime(t1, o.out ? 0 : 100);
    try {
        var easeIn = new KeyframeEase(0, o.ease);
        var easeOut = new KeyframeEase(0, o.ease);
        prog.setTemporalEaseAtKey(1, [easeIn], [easeOut]);
        prog.setTemporalEaseAtKey(2, [easeIn], [easeOut]);
    } catch (e2) {}

    return ctrl;
}

// Effects on the scan layer (look: glass bevel, horizontal smear, color, glow)
function addScanLook(scan, mapIndex, ref) {
    var g = addFx(scan, "CC Glass", "PS Glass");
    if (g) {
        setVal(g, ["Bump Map"], mapIndex);
        setVal(g, ["Softness"], 1);
        setVal(g, ["Height"], -50);
        setExpr(g, ["Displacement"], ref + ".effect(\"Glass Depth\")(1);");
        setVal(g, ["Ambient"], 50);
        setVal(g, ["Diffuse"], 50);
        setVal(g, ["Specular"], 50);
        setVal(g, ["Roughness"], 0.025);
        setVal(g, ["Metal"], 100);
    }

    var smears = [["PS Smear A", ".effect(\"Smear\")(1) * 0.5;"], ["PS Smear B", ".effect(\"Smear\")(1) * -1;"]];
    for (var s = 0; s < smears.length; s++) {
        var dm = addFx(scan, "ADBE Displacement Map", smears[s][0]);
        if (dm) {
            setVal(dm, ["Displacement Map Layer", "ADBE Displacement Map-0001"], mapIndex);
            setExpr(dm, ["Max Horizontal Displacement", "ADBE Displacement Map-0003"], ref + smears[s][1]);
            setVal(dm, ["Max Vertical Displacement", "ADBE Displacement Map-0005"], 0);
            setVal(dm, ["Expand Output"], 1);
        }
    }

    var cr = addFx(scan, "APC Colorama", "PS Rainbow");
    if (cr) {
        setExpr(cr, ["Phase Shift"], ref + ".effect(\"Hue Shift\")(1);");
        setExpr(cr, ["Blend With Original"], "100 - clamp(" + ref + ".effect(\"Rainbow\")(1), 0, 100);");
    }

    var glows = [[12, 1.4], [45, 1.0], [140, 0.6]];
    for (var i = 0; i < glows.length; i++) {
        var gl = addFx(scan, "ADBE Glo2", "PS Glow " + (i + 1));
        if (gl) {
            setVal(gl, ["Glow Threshold", "ADBE Glo2-0002"], 35);
            setExpr(gl, ["Glow Radius", "ADBE Glo2-0003"], glows[i][0] + " * " + ref + ".effect(\"Glow Size\")(1) / 100;");
            setExpr(gl, ["Glow Intensity", "ADBE Glo2-0004"], glows[i][1] + " * " + ref + ".effect(\"Glow Intensity\")(1) / 100;");
        }
    }

    scan.property("ADBE Transform Group").property("ADBE Opacity").expression =
        "clamp(" + ref + ".effect(\"Scan Opacity\")(1), 0, 100);";
}

// ------------------------------------------------------------------
//  Main: build the rig on one layer
// ------------------------------------------------------------------

function applyToLayer(comp, L, o) {
    var id = makeId();
    var base = shortName(L.name);
    var ctrlName = "PixelScan CTRL - " + base + " #" + id;
    var refLocal = "thisComp.layer(\"" + esc(ctrlName) + "\")";
    var refRemote = "comp(\"" + esc(comp.name) + "\").layer(\"" + esc(ctrlName) + "\")";
    var big = Math.round(Math.max(comp.width, comp.height) * 4);

    // 1) Controller null
    var ctrl = buildController(comp, ctrlName, id, o);

    // 2) Scan source: duplicate of the layer + scan-band matte -> pre-comp
    var dup = L.duplicate();
    dup.name = "PS Scan Source";
    try { if (typeof dup.removeTrackMatte === "function" && hasTrackMatteSafe(dup)) { dup.removeTrackMatte(); } } catch (e0) {}

    var band = makeRectShape(comp, "PS Scan Band Matte", exprBandSize(refRemote, big), [0, 0]);
    band.moveBefore(dup);
    addMatteFx(band, refRemote);
    wireWipe(band, refRemote);

    var precompName = "PixelScan Scan - " + base + " #" + id;
    var pre = comp.layers.precompose([band.index, dup.index], precompName, true);
    pre.comment = tagString(id, "precomp");
    try { pre.parentFolder = getFolder(); } catch (e1) {}

    var pSrc = pre.layer("PS Scan Source");
    var pBand = pre.layer("PS Scan Band Matte");
    var fill = addFx(pSrc, "ADBE Fill", "PS Scan Fill");
    if (fill) { setExpr(fill, ["Color", "ADBE Fill-0002"], refRemote + ".effect(\"Scan Color\")(1);"); }
    setMatte(pSrc, pBand);
    pBand.comment = tagString(id, "band");

    var scan = null;
    for (var i = 1; i <= comp.numLayers; i++) {
        if (comp.layer(i).source === pre) { scan = comp.layer(i); break; }
    }
    if (!scan) { throw new Error("Could not find the scan pre-comp layer."); }
    scan.name = "PS Scan - " + base + " #" + id;
    scan.comment = tagString(id, "scan");

    var map = scan.duplicate();
    map.name = "PS Scan Map - " + base + " #" + id;
    map.comment = tagString(id, "map");
    map.enabled = false;
    try { map.shy = true; } catch (e2) {}

    // 3) Reveal matte for the original layer
    var reveal = makeRectShape(comp, "PS Reveal Matte - " + base + " #" + id, [big, big], [-big / 2, 0]);
    reveal.comment = tagString(id, "reveal");
    addMatteFx(reveal, refLocal);
    wireWipe(reveal, refLocal);
    try { reveal.shy = true; } catch (e3) {}

    // 4) Stack order (top -> bottom): CTRL, Scan, Map, Reveal Matte, Layer
    reveal.moveBefore(L);
    map.moveBefore(reveal);
    scan.moveBefore(map);
    ctrl.moveBefore(scan);

    setMatte(L, reveal);

    // 5) Scan look (layer refs set after the final order)
    addScanLook(scan, map.index, refLocal);

    return ctrl;
}

// ------------------------------------------------------------------
//  Remove a rig
// ------------------------------------------------------------------

function removeRigs(comp, layers) {
    var ids = {};
    var count = 0;
    var i, t;
    for (i = 0; i < layers.length; i++) {
        t = readTag(layers[i].comment);
        if (!t) {
            try {
                if (hasTrackMatteSafe(layers[i]) && layers[i].trackMatteLayer) {
                    t = readTag(layers[i].trackMatteLayer.comment);
                }
            } catch (e) {}
        }
        if (t && !ids[t.id]) { ids[t.id] = true; count++; }
    }
    if (count === 0) { return 0; }

    for (i = comp.numLayers; i >= 1; i--) {
        t = readTag(comp.layer(i).comment);
        if (t && ids[t.id]) {
            try { comp.layer(i).locked = false; } catch (e1) {}
            comp.layer(i).remove();
        }
    }
    for (i = app.project.numItems; i >= 1; i--) {
        var it = app.project.item(i);
        if (sqIsComp(it)) {
            t = readTag(it.comment);
            if (t && ids[t.id] && it.usedIn.length === 0) { it.remove(); }
        }
    }
    for (i = app.project.numItems; i >= 1; i--) {
        var f = app.project.item(i);
        if (sqIsFolder(f) && f.name === FOLDER_NAME && f.numItems === 0) { f.remove(); }
    }
    return count;
}


// ------------------------------------------------------------------
//  Squeezy entry point
// ------------------------------------------------------------------
if (!comp) { return "Open a composition first."; }
if (!layers.length) { return "Select the layer(s) to reveal (or a Pixel Scan rig to remove)."; }

if (params.action === "Remove rig") {
    var nr = removeRigs(comp, layers);
    return nr ? "Removed " + nr + " Pixel Scan rig" + (nr > 1 ? "s" : "") : "No Pixel Scan rig found on the selected layers.";
}

var DIRS = { "Left → Right": 90, "Right → Left": 270, "Top → Bottom": 180, "Bottom → Top": 0 };
var dirAngle = DIRS[params.direction]; if (dirAngle === undefined) { dirAngle = 90; }
var isOut = params.mode === "Reveal Out";
if (isOut) { dirAngle = (dirAngle + 180) % 360; }
var opts = {
    direction: dirAngle,
    out: isOut,
    duration: Math.max(0.05, +params.duration || 1.5),
    blockSize: Math.max(2, +params.blockSize || 40),
    scanWidth: Math.max(1, +params.scanWidth || 180),
    rainbow: Math.max(0, Math.min(100, +params.rainbow || 0)),
    color: hexToRgb(params.color) || [0.18, 0.95, 1],
    ease: params.ease ? 45 : 0.1
};

var targets = [], skipped = [], ctrls = [], errors = [], i;
for (i = 0; i < layers.length; i++) {
    var L = layers[i];
    if (sqIsCamOrLight(L)) { skipped.push(L.name); continue; }
    if (readTag(L.comment)) { skipped.push(L.name + " (already a rig)"); continue; }
    if (hasTrackMatteSafe(L)) { skipped.push(L.name + " (has a track matte, precompose it)"); continue; }
    if (L.parent) { skipped.push(L.name + " (parented, precompose it)"); continue; }
    targets.push(L);
}
if (!targets.length) { return "Nothing to apply. Skipped: " + skipped.join(", "); }
for (i = 0; i < targets.length; i++) {
    try { ctrls.push(applyToLayer(comp, targets[i], opts)); }
    catch (err) { errors.push(targets[i].name + ": " + err.toString() + (err.line ? " (line " + err.line + ")" : "")); }
}
for (i = 1; i <= comp.numLayers; i++) { comp.layer(i).selected = false; }
for (i = 0; i < ctrls.length; i++) { ctrls[i].selected = true; }
if (errors.length) { throw new Error(errors.join(" | ")); }
return "Pixel Scan on " + ctrls.length + " layer" + (ctrls.length > 1 ? "s" : "") + ". Tweak it on the \"PixelScan CTRL\" null"
    + (skipped.length ? " (skipped: " + skipped.join(", ") + ")" : "");

// ---- type checks that do not depend on instanceof ----
