    var e = comp.layers.addNull(comp.duration);
    e.name = EFF + k; e.label = 2;
    try { tr(e).property("ADBE Opacity").setValue(100); } catch (e0) {}
    if (is3d) try { e.threeDLayer = true; } catch (e1) {}
